-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only genuinely empty published lessons; add each origin/type once. Independently authored examples.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"تحليل عملية الإبداع","passage":"ابتكر فريق طلابي نموذجًا لحامل يثبّت الكتب عند القراءة. راقب المشكلة أولًا، ورسم ثلاثة حلول، واختبر نموذجًا ثم عدّله ليثبت الكتاب بأمان. يتضح أن الإبداع يجمع الملاحظة والتجريب والمراجعة، وهذا المثال من ضاديوم ولا ينقل نص «لذة الإبداع».","prompt":"ما الخطوة التي سبقت تعديل النموذج؟","correct":"اختبار النموذج","w1":"إلغاء المشكلة","w2":"بيع النموذج فورًا","w3":"حذف الرسم","practice":"صف مشكلة بسيطة في ورشة أو مدرسة، واقترح تصميمًا وحلّين بديلين وكيف ستختبرهما."},{"n":2,"skill":"أسلوب التعجب القياسي","passage":"في «ما أجملَ الإتقانَ!» تعجب قياسي على صيغة «ما أفعَلَه»، حيث «أجملَ» فعل ماض جامد لإنشاء التعجب و«الإتقانَ» مفعول به. وفي «أجمِلْ بالإتقان!» صيغة «أفعِلْ به». يُشترط في التعجب المباشر شروط تخص الفعل الثلاثي التام المتصرف المثبت القابل للتفاوت.","prompt":"ما صيغة التعجب في «ما أجمل الإتقان!»؟","correct":"ما أفعله","w1":"أفعل التفضيل فقط","w2":"أسلوب نفي","w3":"نداء","practice":"كوّن جملتي تعجب على الصيغتين القياسيتين من صفة تصلح للتعجب، ثم وضح المعنى وعلامات الترقيم."},{"n":3,"skill":"السرد: بداية وعقدة وحل","passage":"في مشهد تدريبي مستقل وجد المتدرب فهد مفتاح مخزن الأدوات مفقودًا قبل الحصة، فاستأذن مشرفه للبحث، ثم وجد المفتاح في درج الاستقبال. يظهر تسلسل الأحداث في هدف واضح وعائق وخطوات لحله؛ ولا يمثل قصة رسمية من الكتاب.","prompt":"ما العقدة الأساسية في السرد؟","correct":"فقد مفتاح المخزن","w1":"بدء الحصة","w2":"وجود مشرف","w3":"فتح الدرج بعد العثور عليه","practice":"اكتب قصة قصيرة عن تحدٍّ في التدريب المهني بتسلسل زمني وسبب ونتيجة وحوار موجز."},{"n":4,"skill":"قيم النجاح في العمل","passage":"أعدت فاطمة قائمة فحص قبل تشغيل آلة التدريب، فلاحظت عطلًا بسيطًا وأبلغت المشرف. أصلح الفريق المشكلة قبل العمل. نجاحها ارتبط بالانتباه والسلامة والتعاون أكثر من السرعة؛ وهو نص إثرائي مستقل لا يُنسب إلى قراءة الكتاب.","prompt":"أي سلوك حمى الفريق من المشكلة؟","correct":"الفحص والإبلاغ قبل التشغيل","w1":"تجاهل العطل","w2":"تشغيل الآلة مع وجود الخلل","w3":"العمل دون إشراف","practice":"اكتب فقرة حجاجية تشرح قيمة واحدة في العمل، مستشهدًا بموقف واقعي أو تخيلي محدد."},{"n":5,"skill":"الفرق بين الجملة الاسمية والفعلية","passage":"«المهندسُ دقيقٌ» جملة اسمية تبدأ بمبتدأ مرفوع وخبر مرفوع. «راجعَ المهندسُ الخطةَ» جملة فعلية تبدأ بفعل ماض وفاعله. يتغير التركيز بين وصف الحال والإخبار عن فعل، مع مراعاة أنواع المبتدأ والخبر.","prompt":"أي جملة فعلية مما يلي؟","correct":"راجع المهندس الخطة","w1":"المهندس دقيق","w2":"الورشة نظيفة","w3":"العمل متقن","practice":"اكتب ثلاث جمل اسمية وثلاثًا فعلية تصف نشاطًا مهنيًا، ثم حدد ركنَي كل واحدة."},{"n":6,"skill":"وصف المكان في تقرير واضح","passage":"دخل الطلاب ورشة النجارة؛ كانت طاولات العمل متباعدة، والأدوات مثبتة في خزائن مرقمة، وفتحات التهوية مفتوحة. الوصف الدقيق يحدد ترتيب المكان والضوء والسلامة، ولا يبالغ في استعارات قد تضلل قارئ التقرير.","prompt":"أي تفصيل يساعد في وصف تنظيم الورشة؟","correct":"خزائن أدوات مرقمة","w1":"اسم مدرسة بعيدة","w2":"موعد عطلة قديمة","w3":"لون السماء خارج المدينة فقط","practice":"اكتب وصفًا من ست جمل لمعمل أو ورشة يذكر الأبعاد النسبية والتنظيم وإجراء سلامة مهم."},{"n":7,"skill":"قراءة القصيدة بشاهد موثق","passage":"قصيدة «أوال مهد الحب والجمال» للشاعر المذكور في عنوان الوحدة تحتاج الأبيات الأصلية المرخصة للتحليل والحفظ. نموذج نثري مستقل: «تحتفظ الجزيرة في ذاكرة ساكنيها بصور البحر والأسواق القديمة». تستخلص منه علاقة المكان بالذاكرة، من غير نسبته إلى القصيدة.","prompt":"ما العلاقة التي يبرزها النموذج النثري؟","correct":"صلة المكان بذكريات السكان","w1":"انعدام تاريخ المكان","w2":"تشابه جميع المدن","w3":"منع وصف البحر","practice":"بعد الرجوع للأبيات الأصلية، استخرج صورة بيانية وشاهدًا موثقًا واشرح عاطفة الشاعر دون اختلاق بيت."},{"n":8,"skill":"توسيع الجملة بمتممات","passage":"«صنعَ المتدربُ قطعةً» جملة فعلية بفعل وفاعل ومفعول به، وفي «صنع المتدرب قطعةً من الخشبِ في الورشةِ» أضيف جار ومجرور يوضح المادة وآخر يحدد المكان. المتممات تزيد الدقة ولا تغير الفعل الأساسي.","prompt":"أي عبارة تدل على مكان الصنع؟","correct":"في الورشة","w1":"من الخشب","w2":"المتدرب","w3":"قطعةً","practice":"وسّع ثلاث جمل فعلية في سياق مهني بمفعول أو ظرف أو جار ومجرور، ثم حدد وظيفة كل متمم."},{"n":9,"skill":"حوار عن الانتماء الوطني","passage":"قالت منى: «أحب أن تكون شوارع حينا نظيفة». فأجاب أحمد: «نشارك في حملة تطوعية ونقيس كمية المخلفات المجموعة». يربط الحوار العاطفة الوطنية بعمل جماعي قابل للقياس، ويحترم اختلاف المقترحات.","prompt":"ما المبادرة التي اتفق عليها المتحاوران؟","correct":"حملة تطوعية لتنظيف الحي","w1":"إهمال نظافة المكان","w2":"منع الحوار","w3":"إلغاء العمل الجماعي","practice":"أعد حوارًا مدته دقيقة بين طالبين يقترحان نشاطًا وطنيًا بخطوات تنفيذ ومعيار نجاح."},{"n":10,"skill":"التخطيط لتحقيق حلم مهني","passage":"حلمت هند أن تتقن التصميم ثلاثي الأبعاد. قسمت هدفها إلى تعلم أداة أولًا، وبناء نموذج بسيط ثانيًا، وعرضه للحصول على ملاحظات ثالثًا. يظهر الفرق بين أمنية غير محددة وخطة يمكن متابعة تقدمها.","prompt":"ما الخطوة الأخيرة في خطة هند؟","correct":"عرض النموذج وتلقي الملاحظات","w1":"ترك التدريب","w2":"حذف النموذج","w3":"إلغاء تقسيم الهدف","practice":"اكتب هدفًا مهنيًا واقعيًا لفصل دراسي، وحدد ثلاث خطوات ومقياس متابعة دون ادعاء تحقيقه مسبقًا."},{"n":11,"skill":"دور الظرف والحال في المعنى","passage":"«عملَ الفنيُّ صباحًا» يتضمن ظرف زمان منصوبًا «صباحًا» يبين وقت العمل. «عمل الفنيُّ منتبهًا» يتضمن حالًا منصوبة «منتبهًا» تبين هيئة الفني. اختلاف السؤال «متى؟» و«كيف؟» يساعد على التمييز.","prompt":"ما وظيفة «منتبهًا» في المثال؟","correct":"حال منصوبة","w1":"ظرف زمان","w2":"فاعل","w3":"مبتدأ","practice":"اكتب أربع جمل مهنية بها ظرف زمان وظرف مكان وحال ومفعول به مع بيان أثر كل متمم."},{"n":12,"skill":"المناقشة المسؤولة للأمن الغذائي","passage":"في نشاط تدريبي افترض الفريق أن حساس رطوبة التربة قد يساعد المزارع على تجنب الري الزائد. اقترح إجراء تجربة بمقارنة استهلاك الماء في مجموعتين قبل تأكيد الفائدة. الفكرة فرضية لا نتيجة مثبتة بعد.","prompt":"ما الدليل اللازم لاختبار الفرضية؟","correct":"مقارنة استهلاك الماء بين مجموعتين","w1":"تكرار الادعاء","w2":"ترك الحساس بلا تجربة","w3":"تغيير السؤال كل مرة","practice":"صمم حوارًا من ست مداخلات عن الزراعة الذكية يشمل فكرة وفائدة محتملة وتحفظًا وطريقة اختبار."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=10
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='9a42a857-58d7-428b-80f7-c02a52e69f6b'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='عرب 801 — اللغة العربية للتعليم الفني والمهني' AND u.semester=1 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF coalesce(trim(target_content),'')='' THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الأول. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.',
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_TECH_G10_T1_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',jsonb_build_array(r.correct,r.w1,r.w2,r.w3)),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_TECH_G10_T1_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_TECH_G10_T1_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_TECH_G10_T1_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;